#include <string.h>
#include "cm_normal_display_check.h"
#include "cm_normal_display_vectors.h"
static const uint8_t control[30]={255,255,255,255,255,255,255,0,1,255,2,3,4,255,255,255,4,255,255,255,4,255,255,255,5,255,255,255,5,255};
static void patch(apollo_overlay_state *s,cm_native_io *io,uint16_t field,uint16_t value){if(field<2048u)s->words[field]=value;else if(field==2048u)io->superbank=value;else if(field==2049u)io->interrupt_enabled=value;else io->channel11=value;}
uint8_t cm_normal_display_checkpoint_input(uint8_t n,apollo_overlay_state *s,cm_native_io *io){uint16_t i;if(n>=64u)return 255;cm_normal_display_input(s,io,(uint16_t)(cm_normal_display_numbers[n]/30u));for(i=cm_normal_display_before_offsets[n];i<cm_normal_display_before_offsets[n+1u];++i)patch(s,io,cm_normal_display_before_patch[i][0],cm_normal_display_before_patch[i][1]);return control[cm_normal_display_numbers[n]%30u];}
uint16_t cm_normal_display_checkpoint_check(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){cm_native_io io,old;uint16_t failures=0,f,p,end;uint8_t phase=cm_normal_display_checkpoint_input(n,s,&io);if(phase==255u)return 1;memcpy(before,s,sizeof *s);old=io;if(!cm_normal_display_caller(s,&io,phase))++failures;p=cm_normal_display_after_offsets[n];end=cm_normal_display_after_offsets[n+1u];for(f=0;f<2051u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:f==2049u?old.interrupt_enabled:old.channel11;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:f==2049u?io.interrupt_enabled:io.channel11;if(p<end&&cm_normal_display_after_patch[p][0]==f)expected=cm_normal_display_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
